WITH inner_cte AS ( SELECT SIS_COURSE_DESCRIPTION.DEPARTMENT_NAME, COURSE_CATALOG_SUBJECT_OFFERED.TOTAL_UNITS FROM SIS_SUBJECT_CODE JOIN SIS_COURSE_DESCRIPTION ON SIS_SUBJECT_CODE.COURSE_NUMBER = SIS_COURSE_DESCRIPTION.COURSE JOIN COURSE_CATALOG_SUBJECT_OFFERED ON SIS_COURSE_DESCRIPTION.COURSE = COURSE_CATALOG_SUBJECT_OFFERED.SUBJECT_CODE WHERE COURSE_CATALOG_SUBJECT_OFFERED.ACADEMIC_YEAR = 2022 AND SIS_COURSE_DESCRIPTION.IS_DEGREE_GRANTING = 'Y' AND SIS_COURSE_DESCRIPTION.DEPARTMENT_NAME <> 'Mathematics' AND SIS_COURSE_DESCRIPTION.DEPARTMENT <> '18' ) SELECT ic.DEPARTMENT_NAME, AVG(ic.TOTAL_UNITS) AS avg_total_units, MAX(ic.TOTAL_UNITS) - MIN(ic.TOTAL_UNITS) AS total_units_range, VARIANCE(ic.TOTAL_UNITS) AS total_units_variance FROM inner_cte ic JOIN ( SELECT DEPARTMENT_NAME FROM inner_cte WHERE TOTAL_UNITS > 9 GROUP BY DEPARTMENT_NAME ) dept_with_high_unit ON ic.DEPARTMENT_NAME = dept_with_high_unit.DEPARTMENT_NAME GROUP BY ic.DEPARTMENT_NAME ORDER BY total_units_range DESC;